def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>This guide's two hardest jobs are making things sterile and making a few drugs. These patents show the hardware and the original methods. They run from simple steam sterilizers built around a pot of boiling water, through combined instrument boilers and hot-air and steam cabinets, to an air-ejector steam chamber. Three are drawing-less chemistry and fermentation patents: the U.S. aspirin patent and two of the Peoria penicillin patents. For those the card shows the first page of the specification instead of a drawing. Read them with Parts 5, 6, 9 and 12. The limits in section 1.2 and the purity and dose warnings in 7.3 and 9.3 still apply.</p>"
UNPATENTED = ["Boiling instruments, sun-drying dressings and willow-bark tea are traditional practices that anyone may use."]
PATENTS = [
P("US484927","5a/c3/28/49a65ef94c45c2/US484927.pdf","1b/55/cd/4a0b2ffb16e403/US484927-drawings-page-1.png","A","1892-10-25","Eduard Boeckmann (St. Paul, Minnesota)","Sterilizer for surgical instruments, &c.",
  "A sterilizer using flowing (&ldquo;current&rdquo;) steam at 212&nbsp;&deg;F, which Boeckmann calls a powerful germicide that is easy to produce, made for the working surgeon. It shows a chamber over boiling water that can be copied with a large pot, a rack and a lid (see section 12.1).","Sectional elevation of boiler, steam chamber and trays"),
P("US552157","e2/60/ec/59b43702820a89/US552157.pdf","a5/5d/a6/7ae534aeaf98ad/US552157-drawings-page-1.png","A","1895-12-31","John W. Wallace (Brooklyn, New York)","Sterilizer for bandages, &c.",
  "A hospital or doctor's sterilizer that raises steam quickly to sterilize bandages and towels, and heats a large amount of water at the same time for soaking instruments. It shows the body on legs, the steam space and the removable water tank.","Fig. 1 sectional elevation; Fig. 2 cross-section; Fig. 3 tank"),
P("US578376","db/40/27/0a219e2f693088/US578376.pdf","fa/75/a5/ac16266111f3e1/US578376-drawings-page-1.png","A","1897-03-09","John W. Wallace (Brooklyn, New York)","Sterilizer",
  "A surgeon's sterilizer using heat and live steam for bandages, towels and instruments. The main sterilizing chamber is joined at top and bottom to a water-supply tank, with both openings a little above the chamber floor. It is a simple layout to build from two sheet-metal cans.","Sections through chamber and side tank"),
P("US553561","5b/0e/4b/de4388ee0475e2/US553561.pdf","91/88/0d/bdc85995a2e477/US553561-drawings-page-1.png","B","1896-01-28","Erik M. Lundholm (St. Paul, Minnesota)","Sterilizer for surgical instruments, &c.",
  "An instrument boiler combined with a dressing chamber above it, which is sterilized by the steam from the boiler. The two parts separate so each can be used alone, and an idle steam space around the steam keeps it hot.","Sectional elevation of the boiler and the dressing compartment above"),
P("US720159","71/f9/a7/11c54cb0c2d688/US720159.pdf","c6/fc/8f/1a54ce0ad5a443/US720159-drawings-page-1.png","B","1903-02-10","Richard Kny (Brooklyn, New York)","Sterilizer",
  "A cabinet that sterilizes dressings and instruments quickly with heated air and steam. Kny designed it to be safe, accurate and easy to run.","Fig. 1 longitudinal section with door; Fig. 2 details"),
P("US583514","6a/66/14/2abecdc83e6886/US583514.pdf","17/81/a8/a3c756b3cd6d9a/US583514-drawings-page-1.png","C","1897-06-01","Austin W. M. Sprague (Brooklyn, New York)","Sterilizing apparatus",
  "A steam-jacketed chamber with a tight door and an ejector. The ejector draws the air out before steam goes in, so the steam reaches every part of the load, and draws the steam out before the door opens, so the articles come out dry.","Sheet 1: chamber, jacket and ejector piping"),
P("US2442141","21/87/da/f8ac2a0541d168/US2442141.pdf","pdf:1","C","1948-05-25","Andrew J. Moyer (Peoria, Illinois), assignor to the U.S. Department of Agriculture","Method for production of penicillin",
  "One of the Peoria penicillin patents. Example I gives the surface-culture medium: lactose, sodium nitrate, a trace of zinc sulfate and concentrated corn-steep liquor in water, set out in cotton-plugged flasks and sterilized at 15&nbsp;lb steam pressure. Read it with Part 5. The patent states that the government may use it royalty-free.","No drawings: first specification page shown"),
P("US2443989","db/20/57/0d84013721384a/US2443989.pdf","pdf:1","C","1948-06-22","Andrew J. Moyer (Peoria, Illinois), assignor to the U.S. Department of Agriculture","Method for production of penicillin",
  "Penicillin grown submerged in a liquid nutrient medium, in contact with oxygen-containing gas, instead of on the surface. Moyer notes that surface culture in bottles and pans was laborious, costly and slow (7&ndash;14 days) and needed large incubation rooms. Read it with Part 6 and its yield-reality warning (section 7.4).","No drawings: first specification page shown"),
P("US644077","92/a4/6c/393c2c6f5d0975/US644077.pdf","pdf:1","C","1900-02-27","Felix Hoffmann (Elberfeld, Germany), assignor to Farbenfabriken of Elberfeld Co.","Acetyl salicylic acid",
  "The U.S. aspirin patent. For a survivor, the useful part is the identity checks. Hoffmann says true acetylsalicylic acid splits into acetic and salicylic acid when boiled with water, and its water solution does not turn violet with a little ferric chloride. Salicylic acid does turn violet. That is the basis of the ferric-chloride purity test in section 9.3.","No drawings: specification page shown"),
P("US789237","e9/2d/45/e865e35088c246/US789237.pdf","3b/f5/fa/b31a12276a0b98/US789237-drawings-page-1.png","B","1905-05-09","Charles Edward Skinner","Bacteriological oven or incubator",
  "A laboratory incubator for growing cultures at a steady temperature. The inner chamber sits in a liquid-filled jacket that is heated electrically. A thermostat bar made of two strips of different metals bends as the liquid warms and works a switch (an electromagnet and mercury cups), keeping the temperature nearly uniform for as long as needed. The guide's culture steps call for steady incubation temperatures (Parts 5 and 6).","Fig. 1 section through the oven and jacket; Fig. 2 circuit diagram; Fig. 3 the thermostat"),
]
